import { SimpleGrid, TextInput } from '@mantine/core';
import { MaskedDateInput } from '@mantine/dates';
import { AccountForm } from './types';

interface PersonalFieldsProps {
  form: AccountForm;
}

export function PersonalFields({ form }: PersonalFieldsProps) {
  return (
    <>
      <SimpleGrid cols={{ base: 1, sm: 2 }}>
        <TextInput
          size="md"
          label="First name"
          placeholder="Jane"
          withAsterisk
          {...form.getInputProps('personal.firstName')}
        />

        <TextInput
          size="md"
          label="Last name"
          placeholder="Doe"
          withAsterisk
          {...form.getInputProps('personal.lastName')}
        />
      </SimpleGrid>

      <MaskedDateInput
        size="md"
        label="Birth date"
        withAsterisk
        maxDate={new Date()}
        {...form.getInputProps('personal.birthDate')}
      />
    </>
  );
}

import { UseFormReturnType } from '@mantine/form';

export type AccountType = 'personal' | 'company';

export interface PersonalValues {
  firstName: string;
  lastName: string;
  birthDate: string | null;
}

export interface CompanyValues {
  name: string;
  vatNumber: string;
  contactPerson: string;
}

export interface AccountValues {
  accountType: AccountType;
  personal: PersonalValues;
  company: CompanyValues;
}

export type AccountForm = UseFormReturnType<AccountValues>;
